from pptx import Presentation

prs = Presentation('input.pptx')

for i, slide in enumerate(prs.slides):
    print(f"Slide {i}")
    for j, shape in enumerate(slide.shapes):
        print(f"  Shape {j}: {shape.name}, {shape.shape_type}")
        if shape.has_text_frame:
            print(f"    Text: {shape.text}")
        if shape.shape_type == 7: # Graphic Frame
            if shape.has_chart:
                 print("    Has chart")
            if hasattr(shape, 'ole_format'):
                 print(f"    OLE Object: {shape.ole_format.prog_id}")

import openpyxl

try:
    wb = openpyxl.load_workbook('embedded_excel.xlsx')
    sheet = wb.active
    for row in sheet.iter_rows(values_only=True):
        print(row)
    wb.close()
except Exception as e:
    print(f"Error: {e}")
